<?php
declare(strict_types=1);
require dirname(__DIR__).'/core/bootstrap.php';
try{$c=nexus_config();$gw=nexus_world($_GET['world']??'');$type=strtolower((string)($_GET['type']??''));$id=(int)($_GET['id']??0);if($id<1||!in_array($type,['club','nation'],true))throw new InvalidArgumentException('invalid_team');$core=nexus_db($c,'core');
if($type==='club'){$map=nexus_rows($core,'SELECT m.`Club ID` entity_id,m.`Club Name` name,m.`SM World Club ID` world_id,c.image_url FROM `IMC Game World Club Mapping` m LEFT JOIN `IMC Club Codex Global` c ON c.id=m.`Club ID` WHERE m.`Game World`=? AND m.`SM World Club ID`=? LIMIT 1',[$gw,$id]);$clubId=(int)($map[0]['world_id']??0);$mgr=$clubId?nexus_rows($core,'SELECT manager_id,full_name,start_date,end_date FROM `IMC Manager Assignment Global` WHERE game_world_id=? AND assignment_type=\'club\' AND team_id=? ORDER BY (end_date IS NULL) DESC,start_date DESC,id DESC LIMIT 1',[$gw,$clubId]):[];}
else{$map=nexus_rows($core,'SELECT m.`National Team ID` entity_id,m.`National Team Name` name,m.`SM World National Club ID` world_id,c.image_url FROM `IMC Game World National Team Mapping` m LEFT JOIN `IMC National Team Codex Global` c ON c.id=m.`National Team ID` WHERE m.`Game World`=? AND (m.`SM World National Club ID`=? OR m.`National Team ID`=?) ORDER BY (m.`SM World National Club ID`=?) DESC LIMIT 1',[$gw,$id,$id,$id]);$nation=$map[0]??null;$mgr=$nation?nexus_rows($core,"SELECT manager_id,full_name,start_date,end_date FROM `IMC Manager Assignment Global` WHERE game_world_id=? AND assignment_type='national_team' AND national_team_id IN (?,?) ORDER BY (end_date IS NULL) DESC,start_date DESC,id DESC LIMIT 1",[$gw,(int)$nation['world_id'],(int)$nation['entity_id']]):[];}
nexus_out(['ok'=>true,'game_world_id'=>$gw,'type'=>$type,'team'=>$map[0]??null,'manager'=>$mgr[0]??null]);}catch(InvalidArgumentException $e){nexus_out(['ok'=>false,'error'=>$e->getMessage()],422);}catch(Throwable $e){nexus_out(['ok'=>false,'error'=>'team_detail_error'],500);}
